"""Minimal near miss on a prescribed node set, via the primitive Vandermonde kernel."""

from __future__ import annotations

from math import gcd
from typing import Dict, List, Sequence, Tuple

Multiset = Dict[int, int]


def nodal_weight(nodes: Sequence[int], a: int) -> int:
    """w(a) = prod_{b in A, b != a} (a - b);  nonzero since the nodes are distinct."""
    w = 1
    for b in nodes:
        if b != a:
            w *= (a - b)
    return w


def lcm_list(values: Sequence[int]) -> int:
    out = 1
    for v in values:
        out = out * v // gcd(out, v)
    return out


def primitive_kernel_vector(nodes: Sequence[int]) -> Dict[int, int]:
    """
    The primitive integer generator of the kernel of the truncated (N x (N+1))
    Vandermonde system on A = nodes, i.e. of

        { e : sum_a e(a) a^k = 0  for all k < N },     N + 1 = |A|.

    By the kernel theorem this space is the line spanned by a -> 1 / w(a);
    clearing denominators with L = lcm |w(a)| and dividing by the content gives
    the unique primitive generator up to sign.
    """
    weights = {a: nodal_weight(nodes, a) for a in nodes}
    denom = lcm_list([abs(w) for w in weights.values()])
    raw = {a: (denom // abs(w)) * (1 if w > 0 else -1) for a, w in weights.items()}
    content = 0
    for value in raw.values():
        content = gcd(content, abs(value))
    content = content or 1
    return {a: value // content for a, value in raw.items()}


def minimal_near_miss(nodes: Sequence[int]) -> Tuple[Multiset, Multiset]:
    """Positive and negative parts of the primitive kernel vector."""
    kernel = primitive_kernel_vector(nodes)
    s = {a: v for a, v in kernel.items() if v > 0}
    t = {a: -v for a, v in kernel.items() if v < 0}
    return s, t


def minimal_size(nodes: Sequence[int]) -> int:
    """m(A) = (1/2) sum_a |v(a)|: the cardinality of each side of the minimal near miss."""
    return sum(abs(v) for v in primitive_kernel_vector(nodes).values()) // 2


def power_sum(s: Multiset, k: int) -> int:
    return sum(m * x ** k for x, m in s.items())


def certify(nodes: Sequence[int]) -> List[Tuple[int, int, int, bool]]:
    """Return (k, p_k(s), p_k(t), equal) for k = 0 .. N, verifying the construction."""
    n = len(nodes) - 1
    s, t = minimal_near_miss(nodes)
    return [(k, power_sum(s, k), power_sum(t, k), power_sum(s, k) == power_sum(t, k))
            for k in range(n + 1)]


if __name__ == "__main__":
    for A in ([0, 1, 2, 3, 4], [0, 1, 3, 4], [0, 1, 4, 6, 9, 10], [0, 1, 4, 9]):
        s, t = minimal_near_miss(A)
        print(f"A = {A}: {dict(sorted(s.items()))} vs {dict(sorted(t.items()))}, "
              f"m(A) = {minimal_size(A)}")
        for k, ps, pt, eq in certify(A):
            print(f"   k = {k}: {ps} {'=' if eq else '!='} {pt}")

"""Universality certificate: every test function sees a near miss through one integer."""

from __future__ import annotations

from math import comb, factorial
from typing import Callable, Dict, List, Tuple

Multiset = Dict[int, int]


def even_part(n: int) -> Multiset:
    """Even half of the n-th row of Pascal's triangle, as a multiset of values."""
    return {j: comb(n, j) for j in range(n + 1) if j % 2 == 0}


def odd_part(n: int) -> Multiset:
    """Odd half of the n-th row of Pascal's triangle, as a multiset of values."""
    return {j: comb(n, j) for j in range(n + 1) if j % 2 == 1}


def scaled_pair_with_padding(n: int, lam: int, padding: Multiset
                             ) -> Tuple[Multiset, Multiset]:
    """The general near miss at level n: lam * binomial pair, plus a common padding."""
    s = {x: lam * m for x, m in even_part(n).items()}
    t = {x: lam * m for x, m in odd_part(n).items()}
    for x, m in padding.items():
        s[x] = s.get(x, 0) + m
        t[x] = t.get(x, 0) + m
    return s, t


def weighted_sum(s: Multiset, f: Callable[[int], int]) -> int:
    """sum_{x in s} f(x), counted with multiplicity."""
    return sum(m * f(x) for x, m in s.items())


def forward_difference_at_zero(f: Callable[[int], int], n: int) -> int:
    """(Delta^n f)(0) = sum_{j=0}^{n} (-1)^(n-j) C(n, j) f(j)."""
    return sum((-1) ** (n - j) * comb(n, j) * f(j) for j in range(n + 1))


def universality_certificate(s: Multiset, t: Multiset, n: int,
                             tests: List[Tuple[str, Callable[[int], int]]]
                             ) -> List[Tuple[str, int, int, bool]]:
    """
    For each test function f, compare the true discrepancy with the prediction

        sum_s f - sum_t f  =  lambda * (-1)^n * (Delta^n f)(0),
        lambda = mult_s(0) - mult_t(0).
    """
    lam = s.get(0, 0) - t.get(0, 0)
    rows: List[Tuple[str, int, int, bool]] = []
    for name, f in tests:
        actual = weighted_sum(s, f) - weighted_sum(t, f)
        predicted = lam * (-1) ** n * forward_difference_at_zero(f, n)
        rows.append((name, actual, predicted, actual == predicted))
    return rows


if __name__ == "__main__":
    n = 5
    s, t = scaled_pair_with_padding(n, lam=3, padding={0: 2, 3: 7, 5: 1})
    tests: List[Tuple[str, Callable[[int], int]]] = [
        ("x^3 (degree < N: invisible)", lambda x: x ** 3),
        ("x^5", lambda x: x ** 5),
        ("2^x", lambda x: 2 ** x),
        ("x!", lambda x: factorial(x)),
        ("indicator of primes", lambda x: int(x in (2, 3, 5, 7, 11))),
    ]
    print(f"level N = {n}, lambda = {s.get(0, 0) - t.get(0, 0)}")
    for name, actual, predicted, ok in universality_certificate(s, t, n, tests):
        print(f"  {name:<30} actual {actual:>10}   predicted {predicted:>10}   {ok}")

"""Exhaustive search for the node sets carrying the smallest near miss at a given level."""

from __future__ import annotations

from itertools import combinations
from math import gcd
from typing import Dict, List, Sequence, Tuple


def nodal_weight(nodes: Sequence[int], a: int) -> int:
    w = 1
    for b in nodes:
        if b != a:
            w *= (a - b)
    return w


def lcm_list(values: Sequence[int]) -> int:
    out = 1
    for v in values:
        out = out * v // gcd(out, v)
    return out


def primitive_kernel_vector(nodes: Sequence[int]) -> Dict[int, int]:
    weights = {a: nodal_weight(nodes, a) for a in nodes}
    denom = lcm_list([abs(w) for w in weights.values()])
    raw = {a: (denom // abs(w)) * (1 if w > 0 else -1) for a, w in weights.items()}
    content = 0
    for value in raw.values():
        content = gcd(content, abs(value))
    return {a: value // (content or 1) for a, value in raw.items()}


def minimal_size(nodes: Sequence[int]) -> int:
    """m(A) = (1/2) sum_a |v(a)|, the size of each side of the minimal near miss on A."""
    return sum(abs(v) for v in primitive_kernel_vector(nodes).values()) // 2


def search_level(n: int, window: int) -> Tuple[int, List[Tuple[int, ...]]]:
    """
    Minimise m(A) over node sets A of size n + 1 contained in {0, ..., window},
    normalised by min(A) = 0 (m is translation invariant).

    Complexity: C(window, n) evaluations, each O(n^2) big-integer multiplications.
    """
    best: int | None = None
    minimisers: List[Tuple[int, ...]] = []
    for nodes in combinations(range(window + 1), n + 1):
        if nodes[0] != 0:
            continue
        size = minimal_size(list(nodes))
        if best is None or size < best:
            best, minimisers = size, [nodes]
        elif size == best:
            minimisers.append(nodes)
    assert best is not None
    return best, minimisers


if __name__ == "__main__":
    print(f"{'N':>3} {'min m(A)':>9} {'interval 2^(N-1)':>18}  minimisers (first few)")
    for n in range(1, 6):
        best, minimisers = search_level(n, 3 * n)
        print(f"{n:>3} {best:>9} {2 ** (n - 1):>18}  {minimisers[:3]}")
